// Generate the better-auth tables into server/db/schema.auth.ts via the CLI,
// then re-export them from server/db/schema.ts.
//
// LAW: better-auth schemas are ALWAYS generated by the CLI, never hand-written.
//   1. `bunx auth generate --config scripts/auth.config.ts` (the plugin mirror
//      of server/domains/auth/auth.service.ts)
//   2. post-process — SEMANTIC patches only, never cosmetic ones (Nam's law):
//      no quote/indent/spacing rewrites, the body stays byte-identical to the
//      CLI output except for:
//        - id defaults become $default(() => uuidv7()) — app-minted v7 from
//          the uuid package, never the DB's gen_random_uuid (v4)
//        - apikey.referenceId gains the FK the CLI omits (+ uuid type,
//          matching user.id)
//        - timestamps gain withTimezone (estate law: timestamptz everywhere)
//        - every defaultNow() becomes $default(() => new Date()) —
//          app-minted like the ids; $onUpdate stays verbatim (correct)
//        - the CLI's relations block dropped (the app owns relations via
//          defineRelations in schema.ts), its imports removed with it
//      Every patch asserts it matched — a CLI output change fails generation
//      loudly instead of silently writing drift.
//   3. write server/db/schema.auth.ts; schema.ts re-exports it — no splicing,
//      no generated markers, no way to hand-edit by accident
//
// Usage: bun run gen:auth  (CI re-runs this and fails on any diff — drift guard)
import { execSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const OUT = '/tmp/tandem-auth-schema.ts'
execSync(`bunx auth generate --config scripts/auth.config.ts --output ${OUT} -y`, { stdio: 'pipe' })
let gen = readFileSync(OUT, 'utf8')

// --- semantic patches (each asserts it matched) ---
function patched(needle: string, replacement: string, what: string): void {
  const before = gen
  gen = gen.split(needle).join(replacement)
  if (gen === before) throw new Error(`gen:auth post-process missed: ${what}`)
}

// 1) ids mint at the APP: uuidv7 from the uuid package, not the DB's v4
const idDefCount = gen.split('.default(sql`pg_catalog.gen_random_uuid()`)').length - 1
gen = gen.split('.default(sql`pg_catalog.gen_random_uuid()`)').join('.$default(() => uuidv7())')
if (idDefCount === 0) throw new Error('gen:auth post-process missed: id gen_random_uuid defaults')
patched('import { pgTable, text, timestamp, boolean, integer, uuid, index } from "drizzle-orm/pg-core";',
  'import { pgTable, text, timestamp, boolean, integer, uuid, index } from "drizzle-orm/pg-core";\nimport { v7 as uuidv7 } from "uuid";',
  'uuidv7 import line')

// 2) apikey.referenceId FK the CLI omits (uuid type to match user.id)
patched("referenceId: text('reference_id').notNull(),",
  "referenceId: uuid('reference_id').notNull().references(()=> user.id, { onDelete: 'cascade' }),",
  'apikey referenceId FK')

// 3) timestamptz everywhere
const tzCount = gen.match(/timestamp\((['"])[a-z_]+\1\)/g)?.length ?? 0
gen = gen.replace(/timestamp\((['"])([a-z_]+)\1\)/g, "timestamp('$2', { withTimezone: true })")
if (tzCount === 0) throw new Error('gen:auth post-process missed: timestamp columns')

// 4) timestamps mint at the APP (like ids and $onUpdate) — never the DB clock.
// The CLI is ragged per table (session/account omit the updatedAt default,
// apikey omits both + $onUpdate) — normalize every table to the same shape:
// created_at $default().notNull(), updated_at $default().$onUpdate().notNull()
const nowCount = gen.split('.defaultNow()').length - 1
gen = gen.split('.defaultNow()').join('.$default(() => new Date())')
if (nowCount === 0) throw new Error('gen:auth post-process missed: defaultNow columns')
const uOnUpdate = gen.split("timestamp('updated_at', { withTimezone: true }).$onUpdate").length - 1
gen = gen.split("timestamp('updated_at', { withTimezone: true }).$onUpdate").join("timestamp('updated_at', { withTimezone: true }).$default(() => new Date()).$onUpdate")
if (uOnUpdate === 0) throw new Error('gen:auth post-process missed: updatedAt $onUpdate-only columns')
const bareUpdated = gen.split("timestamp('updated_at', { withTimezone: true }).notNull()").length - 1
gen = gen.split("timestamp('updated_at', { withTimezone: true }).notNull()").join("timestamp('updated_at', { withTimezone: true }).$default(() => new Date()).$onUpdate(() => /* @__PURE__ */ new Date()).notNull()")
if (bareUpdated === 0) throw new Error('gen:auth post-process missed: bare updatedAt columns')
const bareCreated = gen.split("timestamp('created_at', { withTimezone: true }).notNull()").length - 1
gen = gen.split("timestamp('created_at', { withTimezone: true }).notNull()").join("timestamp('created_at', { withTimezone: true }).$default(() => new Date()).notNull()")
if (bareCreated === 0) throw new Error('gen:auth post-process missed: bare createdAt columns')

// 5) drop the relations part — the app owns relations via defineRelations
const relIdx = gen.indexOf('export const authRelations')
if (relIdx === -1) throw new Error('gen:auth post-process missed: relations block')
gen = gen.slice(0, relIdx)
// its imports become unused — remove exactly those (never the pg-core line)
patched('import { defineRelationsPart, sql } from "drizzle-orm";\n', '', 'relations import line')
const bodyNoImports = gen.split('\n').filter(l => !l.startsWith('import')).join('\n')
if (/\bdefineRelationsPart\b/.test(bodyNoImports)) throw new Error('gen:auth: defineRelationsPart still referenced')
if (/\bsql\b/.test(bodyNoImports)) throw new Error('gen:auth: sql still referenced — add the import back before shipping')

const header = `// GENERATED by the better-auth CLI — regenerate with \`bun run gen:auth\`.
// NEVER hand-edit: CI reruns the generator and fails on any diff.
// Semantic patches only (id $default(uuidv7) / apikey FK / timestamptz / createdAt
// $default / relations block) — everything else is the CLI output verbatim, formatting
// quirks included.
// (script: scripts/gen-auth-schema.ts; config mirror: scripts/auth.config.ts)
`
writeFileSync('server/db/schema.auth.ts', header + gen.trimEnd() + '\n')
console.log('server/db/schema.auth.ts regenerated from better-auth config')
